INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Gilt das Arbeitsrecht nur für Festangestellte?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Teilzeit, Freelancer etc."}, {"text": "Ja", "correct": false, "because": "Breitere Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit dem Arbeitsrecht?', 3, '[{"text": "Schutz der Arbeitnehmer", "correct": true, "because": "Sichert Rechte"}, {"text": "Gewinnmaximierung", "correct": false, "because": "Nicht primär"}, {"text": "Steuersenkung", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente gehören zum Arbeitsrecht?', 5, '[{"text": "Arbeitsverträge", "correct": true, "because": "Regeln Verhältnis"}, {"text": "Arbeitszeitschutz", "correct": true, "because": "Schützt Gesundheit"}, {"text": "Steuerrecht", "correct": false, "because": "Andere Rechtssparte"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Das Arbeitsrecht regelt Kündigungsfristen. b) Es gilt nur für große Firmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Firmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Anwendung des Arbeitsrechts?', 4, '[{"text": "Gesetzliche Vorgaben", "correct": false, "because": "Grundlage"}, {"text": "Arbeitsverträge", "correct": false, "because": "Kernbestandteil"}, {"text": "Bürodekor", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Arbeitsrecht Arbeitszeiten regelt?', 2, '[{"text": "Ja", "correct": true, "because": "Arbeitszeitgesetz"}, {"text": "Nein", "correct": false, "because": "Teil des Arbeitsrechts"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz gehört zum Arbeitsrecht?', 3, '[{"text": "Kündigungsschutzgesetz", "correct": true, "because": "Schützt Arbeitnehmer"}, {"text": "Einkommenssteuergesetz", "correct": false, "because": "Steuerrecht"}, {"text": "Verkehrsordnung", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Anwendung des Arbeitsrechts?', 5, '[{"text": "Mindestlohn", "correct": true, "because": "Gesetzlich geregelt"}, {"text": "Urlaubsanspruch", "correct": true, "because": "Arbeitnehmerschutz"}, {"text": "Produktgarantie", "correct": false, "because": "Verbraucherrecht"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Arbeitsrecht schützt vor Diskriminierung. b) Es gilt nur für Arbeitgeber. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für beide Seiten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist im Arbeitsrecht unwichtig?', 4, '[{"text": "Arbeitszeitregelung", "correct": false, "because": "Schlüsselaspekt"}, {"text": "Kündigungsschutz", "correct": false, "because": "Kernregelung"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein rechtlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Gilt das Arbeitsrecht international?', 2, '[{"text": "Nein", "correct": true, "because": "Länderspezifisch"}, {"text": "Ja", "correct": false, "because": "National geregelt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringt das Arbeitsrecht?', 4, '[{"text": "Rechtssicherheit", "correct": true, "because": "Klarheit für beide Parteien"}, {"text": "Arbeitnehmerschutz", "correct": true, "because": "Sichert Rechte"}, {"text": "Höhere Gewinne", "correct": false, "because": "Kein direkter Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass das Arbeitsrecht nur Arbeitnehmer schützt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Arbeitgeberrechte"}, {"text": "Ja", "correct": false, "because": "Beidseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich im Arbeitsrecht?', 3, '[{"text": "Arbeitnehmerschutz", "correct": true, "because": "Hauptfokus"}, {"text": "Steuererleichterung", "correct": false, "because": "Anderer Bereich"}, {"text": "Firmenimage", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Arbeitsrecht regelt Arbeitszeiten. b) Es gilt nur für Vollzeitkräfte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gilt für alle Arbeitsformen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat fehlendes Arbeitsrecht?', 5, '[{"text": "Rechtsunsicherheit", "correct": true, "because": "Keine klaren Regeln"}, {"text": "Ausbeutung", "correct": true, "because": "Keine Schutzmechanismen"}, {"text": "Schnellere Prozesse", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist im Arbeitsrecht unwichtig?', 3, '[{"text": "Urlaubsregelung", "correct": false, "because": "Kernbestandteil"}, {"text": "Kündigungsfristen", "correct": false, "because": "Wichtig"}, {"text": "Betriebsausflüge", "correct": true, "because": "Kein rechtlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Regelt das Arbeitsrecht den Mindestlohn?', 3, '[{"text": "Ja", "correct": true, "because": "Gesetzlich festgelegt"}, {"text": "Nein", "correct": false, "because": "Teil des Arbeitsrechts"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob das Arbeitsrecht Tarifverträge umfasst?', 2, '[{"text": "Ja", "correct": true, "because": "Teil der Regelungen"}, {"text": "Nein", "correct": false, "because": "Einbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Recht wähle ich für Kündigungsschutz?', 4, '[{"text": "Kündigungsschutzgesetz", "correct": true, "because": "Schützt Arbeitnehmer"}, {"text": "Betriebsverfassungsgesetz", "correct": false, "because": "Andere Regelungen"}, {"text": "Steuergesetz", "correct": false, "because": "Falscher Bereich"}]');
